'use strict';
const $=id=>document.getElementById(id);
const definitions=[{id:'zz',title:'① 直接测 z',axis:'z',retained:1000,q:[1,0]},{id:'zx',title:'② 改测 x',axis:'x',retained:1000,q:[.5,.5]},{id:'zxz',title:'③ 保留 x+<br>　 再测 z',axis:'z',retained:500,q:[.5,.5]}];
const revealed=new Set();
const math=(tex,cls='')=>'<span class="'+cls+'" data-math="'+tex+'"></span>';
function instrument(x){return '<rect x="'+x+'" y="42" width="106" height="64" rx="4" fill="#e4edf5" stroke="#829bae" stroke-width="2"/>';}
function beam(x1,y1,x2,y2,id,gray=false,dash=false){return '<path d="M'+x1+' '+y1+'L'+x2+' '+y2+'" fill="none" stroke="'+(gray?'#8495a5':'#0070c0')+'" stroke-width="4" '+(dash?'stroke-dasharray="7 6" ':'')+'marker-end="url(#'+(gray?'gray':'blue')+'-'+id+')"/>';}
function geometry(d){const id=d.id,seq=id==='zxz';return '<svg viewBox="0 0 650 '+(seq?184:132)+'" aria-hidden="true"><defs>'+['blue','gray'].map((c,i)=>'<marker id="'+c+'-'+id+'" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0L10 5L0 10Z" fill="'+(i?'#8495a5':'#0070c0')+'"/></marker>').join('')+'</defs>'+beam(2,74,76,74,id)+instrument(80)+(seq?beam(188,58,416,58,id)+beam(188,90,278,150,id,true)+'<rect x="278" y="128" width="16" height="42" fill="#607284"/>'+instrument(420)+beam(528,58,642,42,id)+beam(528,91,642,102,id):beam(188,58,642,42,id)+beam(188,91,642,102,id,d.id==='zz'&&d.revealed,d.id==='zz'&&d.revealed))+'</svg>';}
function draw(){const reference=$('reference').value;const rows=definitions.map(d=>({...d,revealed:revealed.has(d.id),prob:reference==='initial'?d.q.map(p=>p*d.retained/1000):d.q,counts:d.q.map(p=>p*d.retained)}));
$('experiments').innerHTML=rows.map(d=>'<section class="experiment" data-id="'+d.id+'" data-revealed="'+d.revealed+'"><div class="row-heading"><h2>'+d.title+'</h2><button data-reveal="'+d.id+'" aria-expanded="'+d.revealed+'">'+(d.revealed?'隐藏结果':'揭示结果')+'</button></div><div class="setup">'+geometry(d)+math('\\mathrm{SG}\\;'+(d.id==='zxz'?'x':d.axis),'label device-label')+(d.id==='zxz'?math('\\mathrm{SG}\\;z','label device-label second-device')+'<div class="label retained">保留'+(d.revealed?'500个':'？')+'</div>'+math('|x+\\rangle','label current')+'<div class="label blocked">挡住 '+math('x-')+(d.revealed?'：500个':'')+'</div>':'')+'</div><div class="outputs">'+d.prob.map((p,i)=>'<div class="outlet '+(i?'negative':'positive')+'">'+math(d.axis+(i?'-':'+'))+'<span class="value">'+(d.revealed?Math.round(p*100)+'%':'？')+'</span><span class="counts">'+(d.revealed?d.counts[i]+'个':'')+'</span></div>').join('')+(d.id==='zxz'?'<div class="outputs-caption">'+(d.revealed?'':'末台两路各占多少？')+'</div>':'')+'</div></section>').join('');
document.querySelectorAll('[data-math]').forEach(el=>katex.render(el.dataset.math,el,{throwOnError:true,strict:'error'}));
$('basis-note').textContent=revealed.has('zxz')?'第三组每路：250 / 1000 = 25%；相对保留的500个，均为50%。':'先比较前两组，再预测第三组。';
$('reveal-all').textContent=revealed.size===3?'全部隐藏':'全部揭示';window.labState={reference,rows};}
$('experiments').addEventListener('click',e=>{const b=e.target.closest('[data-reveal]');if(!b)return;const id=b.dataset.reveal;revealed.has(id)?revealed.delete(id):revealed.add(id);draw();document.querySelector('[data-reveal="'+id+'"]').focus();});
$('reference').addEventListener('change',draw);$('reveal-all').addEventListener('click',()=>{if(revealed.size===3)revealed.clear();else definitions.forEach(d=>revealed.add(d.id));draw();});$('reset').addEventListener('click',()=>{revealed.clear();$('reference').value='initial';draw();});
function fit(){const scale=Math.min(innerWidth/1216,innerHeight/542);$('slide').style.transform='scale('+scale+')';$('slide').style.left=(innerWidth-1216*scale)/2+'px';$('slide').style.top=(innerHeight-542*scale)/2+'px';}
window.addEventListener('resize',fit);document.addEventListener('fullscreenchange',()=>{$('fullscreen').textContent=document.fullscreenElement?'退出全屏':'全屏';fit();});
let fallback=false;$('fullscreen').addEventListener('click',async()=>{if(fallback){window.open(location.href,'_blank','noopener');return;}try{if(document.fullscreenElement)await document.exitFullscreen();else await document.documentElement.requestFullscreen();}catch{fallback=true;$('fullscreen').textContent='新窗口放大';}});
draw();fit();
